function rebuildBalance(snapshot, eventsSinceSnapshot) {
  let balance = snapshot ? snapshot.balance : 0;

  for (const event of eventsSinceSnapshot) {
    if (event.type === 'MoneyDeposited') balance += event.amount;
    if (event.type === 'MoneyWithdrawn') balance -= event.amount;
  }

  return balance; // same answer as a full replay, far fewer events touched
}

