const events = [
  { type: 'AccountOpened' },
  { type: 'MoneyDeposited', amount: 1000 },
  { type: 'MoneyDeposited', amount: 500 },
  { type: 'MoneyWithdrawn', amount: 200 },
  { type: 'MoneyDeposited', amount: 300 },
  { type: 'MoneyWithdrawn', amount: 150 }
];

function replay(events) {
  return events.reduce((balance, event) => {
    if (event.type === 'MoneyDeposited') return balance + event.amount;
    if (event.type === 'MoneyWithdrawn') return balance - event.amount;
    return balance; // AccountOpened and anything else leaves balance unchanged
  }, 0);
}

console.log(replay(events)); // 1450

